package practice.e;

import java.time.LocalDate;

// TODO: make this a JPA entity on table "coupon": a named UNIQUE constraint on code.
// TODO: Long id generated by the database (IDENTITY); code not null length 30; percentOff not null; validUntil not null;
//       maxRedemptions not null; redemptions not null (starts at 0). Add a protected no-arg constructor for JPA.
//       Why no setter for `redemptions`? (who is allowed to change it?)
public class Coupon {
    private Long id;
    private String code;
    private int percentOff;
    private LocalDate validUntil;
    private int maxRedemptions;
    private int redemptions;

    public Coupon(String code, int percentOff, LocalDate validUntil, int maxRedemptions) {
        this.code = code;
        this.percentOff = percentOff;
        this.validUntil = validUntil;
        this.maxRedemptions = maxRedemptions;
    }

    public Long getId() { return id; }
    public String getCode() { return code; }
    public int getPercentOff() { return percentOff; }
    public LocalDate getValidUntil() { return validUntil; }
    public int getMaxRedemptions() { return maxRedemptions; }
    public int getRedemptions() { return redemptions; }
}
